import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Atlas region aspect ratio: 512 x 320
  const aspectRatio = 512 / 320;

  // Create plane geometry with proper aspect ratio
  const height = 1.0;
  const width = height * aspectRatio;
  const geometry = new THREE.PlaneGeometry(width, height);

  // Load texture from imageUrl
  const textureObj = ctx.textureLoader.load(config.assets.imageUrl);

  // Create material with TSL texture node
  const texNode = texture(textureObj);
  const material = new MeshBasicNodeMaterial({
    colorNode: texNode,
    transparent: true,
    side: THREE.DoubleSide
  });

  const mesh = new THREE.Mesh(geometry, material);

  // Apply transforms from config
  const pos = config.position || {};
  const rot = config.rotation || {};
  const scl = config.scale || {};

  mesh.position.set(pos.x ?? 0, pos.y ?? 0, pos.z ?? 0);
  mesh.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);
  mesh.scale.set(scl.x ?? 1, scl.y ?? 1, scl.z ?? 1);

  group.add(mesh);

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureObj.dispose();
  };

  return group;
}
